function validate([nums]) {
  if (nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => v < 0 || v > 1000000000)) return 'Each value is between 0 and 10^9.';
  return null;
}

