function totalHammingDistance(nums) {
  const n = nums.length;
  let total = 0;
  for (let bit = 0; bit < 30; bit++) {
    let ones = 0;
    for (const num of nums) {
      ones += (num >> bit) & 1;
    }
    total += ones * (n - ones);
  }
  return total;
}

