function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [Array.from({ length: 2000 }, () => pick(1000000001))];
  const n = 1 + pick(8);
  const style = pick(4);
  const value = () => {
    if (style === 0) return pick(8);
    if (style === 1) return 1000000000 - pick(3);
    if (style === 2) return 2 ** pick(30);
    return pick(1000000001);
  };
  return [Array.from({ length: n }, value)];
}
